echo "Test: draft + dispatch:reviewed + failing CI → fix-checks"
setup
printf '[%s]\n' "$(make_pr 10 "42-my-feature" "true" '[{"name":"dispatch:reviewed"}]' "$FAILING_ROLLUP")" \
