echo "Test: CONFLICTING + green + reviewed → fix-conflicts (outranks review)"
setup
printf '[%s]\n' "$(make_pr_mergeable 10 "42-my-feature" "true" '[{"name":"dispatch:reviewed"}]' "$GREEN_ROLLUP" "CONFLICTING")" \
  > "$STUB_DIR/pr-list-full.json"
