printf '[{"number":5500}]\n' > "$STUB_DIR/subissues-55.json"
printf '{"title":"Issue 5500","body":"","comments":[],"number":5500,"state":"OPEN"}\n' \
  > "$STUB_DIR/issue-5500.json"
printf 'worktree /repo\nHEAD abc123\n\n' > "$STUB_DIR/worktree-list.txt"
