# JS6. Two eligible jits → the earlier-due one wins (verifies due arithmetic).
echo "Test: JIT scan — two eligible jits, earlier due wins"
setup
printf '%s\n' "$JIT_PROJECTS_JSON" > "$DISPATCH_CONFIG_DIR/projects.json"
