if grep -q 'FBCA04' "$SCRIPT_DIR/dispatch-apply-office-hours"; then
  PASS=$((PASS + 1)); echo "  PASS: dispatch-apply-office-hours owns FBCA04"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: dispatch-apply-office-hours owns FBCA04"
fi

