  {"sessionId":"a","pid":1,"status":"busy","name":"824-foo"},
  {"sessionId":"b","pid":2,"status":"busy","name":"720-bar"},
  {"sessionId":"c","pid":3,"status":"idle","name":"508-bar"},
  {"sessionId":"d","pid":4,"status":"busy","name":"dispatch-abcd"},
