if [[ "$(realpath "$sj_pwd_line" 2>/dev/null)" == "$(realpath "$SPAWN_JOB_CWD")" ]]; then
  PASS=$((PASS + 1)); echo "  PASS: spawn-job: 'claude --bg' ran with cwd = the passed --cwd"
