# ============================================================================

echo "Test: dispatch-open-pr"

# Dedicated setup/teardown modeled on followup_exists_setup/teardown. Builds a
# temp tree with the script under test and a gh stub on PATH. The gh stub
# EMULATES GitHub's close parser: it reads the body passed to `pr create` /
# `pr edit`, extracts every `<keyword> #N`, and writes the resulting close set
# to $TREE/close-set.txt — which `pr view` then echoes back. The force-extra /
# force-drop knobs override the parsed set deterministically.
open_pr_setup() {
  TMPDIR_TEST=$(mktemp -d)
  mkdir -p "$TMPDIR_TEST/scripts" "$TMPDIR_TEST/bin"

  cp "$SCRIPT_DIR/dispatch-open-pr" "$TMPDIR_TEST/scripts/dispatch-open-pr"
  chmod +x "$TMPDIR_TEST/scripts/dispatch-open-pr"

  cat > "$TMPDIR_TEST/bin/gh" <<'STUB'
#!/usr/bin/env bash
# gh stub emulating GitHub's close parser for dispatch-open-pr tests.
TREE="$(cd "$(dirname "$0")/.." && pwd)"

# Locate the value following --body-file in the argument list.
body_file=""
prev=""
for a in "$@"; do
  if [[ "$prev" == "--body-file" ]]; then
    body_file="$a"
  fi
  prev="$a"
done

# Parse the close set from a body file the same way GitHub does, then apply the
# force-extra / force-drop knobs and write the sorted-unique result.
write_close_set() {
  local bf="$1"
  local set=""
  if [[ -n "$bf" && -f "$bf" ]]; then
    # Extract "<keyword> [:] #N" → bare N, case-insensitive.
    set="$(grep -ioE '(close[sd]?|fix(e[sd])?|resolve[sd]?)[ \t]*:?[ \t]*#[0-9]+' "$bf" \
      | grep -oE '#[0-9]+' | tr -d '#' || true)"
  fi
  # force-extra: add a number.
  if [[ -f "$TREE/force-extra" ]]; then
    set="$set
$(cat "$TREE/force-extra")"
  fi
  # force-drop: remove a number.
  if [[ -f "$TREE/force-drop" ]]; then
    local drop
    drop="$(cat "$TREE/force-drop")"
    set="$(printf '%s\n' "$set" | grep -vxF "$drop" || true)"
  fi
  printf '%s\n' "$set" | grep -E '^[0-9]+$' | sort -n -u > "$TREE/close-set.txt" || true
}

case "$1 $2" in
  "pr create")
    cp "$body_file" "$TREE/last-body.txt"
    write_close_set "$body_file"
    echo "https://github.com/natb1/commons.systems/pull/1500"
    ;;
  "pr edit")
    cp "$body_file" "$TREE/last-body.txt"
    write_close_set "$body_file"
    echo "edit" >> "$TREE/edit-calls.log"
    echo "https://github.com/natb1/commons.systems/pull/1500"
    ;;
  "pr view")
    if [[ -f "$TREE/close-set.txt" ]]; then
      cat "$TREE/close-set.txt"
    fi
    ;;
  *)
    echo "gh stub: unknown invocation: $*" >&2
    exit 1
    ;;
esac
STUB
  chmod +x "$TMPDIR_TEST/bin/gh"

  SAVED_PATH_OP="$PATH"
  export PATH="$TMPDIR_TEST/bin:$PATH"
}

open_pr_teardown() {
  rm -rf "$TMPDIR_TEST"
  TMPDIR_TEST=""
  export PATH="$SAVED_PATH_OP"
}

# CASE 1 — clean single close: prose-only body file, no --closes.
open_pr_setup
echo "Some descriptive prose." > "$TMPDIR_TEST/body.txt"
out=$("$TMPDIR_TEST/scripts/dispatch-open-pr" 1119 --title "t" --body-file "$TMPDIR_TEST/body.txt" 2>/dev/null) && rc=0 || rc=$?
assert_eq "open-pr: clean single close → stdout PR number" "1500" "$out"
assert_eq "open-pr: clean single close → rc 0" "0" "$rc"
open_pr_teardown

# CASE 2 — multi-close + normalization ("1120, #1121").
open_pr_setup
echo "Body prose." > "$TMPDIR_TEST/body.txt"
out=$("$TMPDIR_TEST/scripts/dispatch-open-pr" 1119 --title "t" --closes "1120, #1121" --body-file "$TMPDIR_TEST/body.txt" 2>/dev/null) && rc=0 || rc=$?
assert_eq "open-pr: multi-close → stdout PR number" "1500" "$out"
assert_eq "open-pr: multi-close → rc 0" "0" "$rc"
close_set="$(cat "$TMPDIR_TEST/close-set.txt")"
assert_eq "open-pr: multi-close → close set is the three numbers" "$(printf '1119\n1120\n1121')" "$close_set"
assert_eq "open-pr: multi-close → body has Closes #1119" "1" "$(grep -cxF 'Closes #1119' "$TMPDIR_TEST/last-body.txt")"
assert_eq "open-pr: multi-close → body has Closes #1120" "1" "$(grep -cxF 'Closes #1120' "$TMPDIR_TEST/last-body.txt")"
assert_eq "open-pr: multi-close → body has Closes #1121" "1" "$(grep -cxF 'Closes #1121' "$TMPDIR_TEST/last-body.txt")"
open_pr_teardown

# CASE 3 — stray "fixes #999" in prose → corrected via edit.
open_pr_setup
printf 'This change also fixes #999 in passing.\n' > "$TMPDIR_TEST/body.txt"
out=$("$TMPDIR_TEST/scripts/dispatch-open-pr" 1119 --title "t" --body-file "$TMPDIR_TEST/body.txt" 2>/dev/null) && rc=0 || rc=$?
assert_eq "open-pr: stray fixes #999 → stdout PR number" "1500" "$out"
assert_eq "open-pr: stray fixes #999 → rc 0" "0" "$rc"
assert_eq "open-pr: stray fixes #999 → an edit occurred" "1" "$([[ -s "$TMPDIR_TEST/edit-calls.log" ]] && echo 1 || echo 0)"
assert_eq "open-pr: stray fixes #999 → final close set is just 1119" "1119" "$(cat "$TMPDIR_TEST/close-set.txt")"
assert_eq "open-pr: stray fixes #999 → keyword stripped from corrected body" "0" "$(grep -cE '(close[sd]?|fix(e[sd])?|resolve[sd]?)[ \t]*:?[ \t]*#999' "$TMPDIR_TEST/last-body.txt" || true)"
open_pr_teardown

# CASE 4 — force-extra=777: an extra the script cannot strip (no keyword in body
# produces it) → correction fails, rc non-zero, stderr names 777.
open_pr_setup
echo "Body prose." > "$TMPDIR_TEST/body.txt"
echo 777 > "$TMPDIR_TEST/force-extra"
out=$("$TMPDIR_TEST/scripts/dispatch-open-pr" 1119 --title "t" --body-file "$TMPDIR_TEST/body.txt" 2>"$TMPDIR_TEST/err.txt") && rc=0 || rc=$?
assert_eq "open-pr: unresolvable extra → rc non-zero" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
assert_eq "open-pr: unresolvable extra → stderr names 777" "1" "$(grep -c '777' "$TMPDIR_TEST/err.txt")"
open_pr_teardown

# CASE 5 — force-drop=1119: an intended number missing → rc non-zero, stderr
# names 1119.
open_pr_setup
echo "Body prose." > "$TMPDIR_TEST/body.txt"
echo 1119 > "$TMPDIR_TEST/force-drop"
out=$("$TMPDIR_TEST/scripts/dispatch-open-pr" 1119 --title "t" --body-file "$TMPDIR_TEST/body.txt" 2>"$TMPDIR_TEST/err.txt") && rc=0 || rc=$?
assert_eq "open-pr: missing intended → rc non-zero" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
assert_eq "open-pr: missing intended → stderr names 1119" "1" "$(grep -c '1119' "$TMPDIR_TEST/err.txt")"
open_pr_teardown

# CASE 6 — prose via stdin (no --body-file).
open_pr_setup
out=$(echo "some prose" | "$TMPDIR_TEST/scripts/dispatch-open-pr" 1119 --title t 2>/dev/null) && rc=0 || rc=$?
assert_eq "open-pr: stdin prose → stdout PR number" "1500" "$out"
assert_eq "open-pr: stdin prose → rc 0" "0" "$rc"
assert_eq "open-pr: stdin prose → close set is 1119" "1119" "$(cat "$TMPDIR_TEST/close-set.txt")"
open_pr_teardown

# CASE 7 — usage errors.
open_pr_setup
out=$("$TMPDIR_TEST/scripts/dispatch-open-pr" --title t 2>/dev/null) && rc=0 || rc=$?
assert_eq "open-pr: missing primary → rc non-zero" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
out=$("$TMPDIR_TEST/scripts/dispatch-open-pr" abc --title t 2>/dev/null) && rc=0 || rc=$?
assert_eq "open-pr: non-numeric primary → rc non-zero" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
out=$("$TMPDIR_TEST/scripts/dispatch-open-pr" 1119 2>/dev/null) && rc=0 || rc=$?
assert_eq "open-pr: missing --title → rc non-zero" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
open_pr_teardown

# CASE 8 — primary repeated in --closes is deduped to a single Closes line.
open_pr_setup
echo "Body prose." > "$TMPDIR_TEST/body.txt"
out=$("$TMPDIR_TEST/scripts/dispatch-open-pr" 1119 --title "t" --closes "1119 1120" --body-file "$TMPDIR_TEST/body.txt" 2>/dev/null) && rc=0 || rc=$?
assert_eq "open-pr: dedup primary → stdout PR number" "1500" "$out"
assert_eq "open-pr: dedup primary → rc 0" "0" "$rc"
assert_eq "open-pr: dedup primary → exactly one Closes #1119 line" "1" "$(grep -cxF 'Closes #1119' "$TMPDIR_TEST/last-body.txt")"
assert_eq "open-pr: dedup primary → close set is 1119 1120" "$(printf '1119\n1120')" "$(cat "$TMPDIR_TEST/close-set.txt")"
open_pr_teardown

echo ""
echo "=== dispatch-refresh-rate-limits ==="

# Headless telemetry probe for #1127. The network fetch is replaced by the
# DISPATCH_REFRESH_RATE_LIMITS_HEADERS_FILE seam — tests NEVER make a real
# request. update-rate-limits.sh's writer-path override
# (DISPATCH_RATE_LIMITS_STATE_FILE) points the atomic write at a temp file.

rr_setup() {
  TMPDIR_TEST=$(mktemp -d)
  mkdir -p "$TMPDIR_TEST/scripts" "$TMPDIR_TEST/state" "$TMPDIR_TEST/fix"
  cp "$SCRIPT_DIR/dispatch-refresh-rate-limits" "$TMPDIR_TEST/scripts/"
  cp "$SCRIPT_DIR/update-rate-limits.sh" "$TMPDIR_TEST/scripts/"
  cp "$SCRIPT_DIR/dispatch-target-workers" "$TMPDIR_TEST/scripts/"
  cp "$SCRIPT_DIR/dispatch-config-load" "$TMPDIR_TEST/scripts/"
  cp "$SCRIPT_DIR/lib.sh" "$TMPDIR_TEST/scripts/"
  chmod +x "$TMPDIR_TEST/scripts/dispatch-refresh-rate-limits" \
           "$TMPDIR_TEST/scripts/update-rate-limits.sh" \
           "$TMPDIR_TEST/scripts/dispatch-target-workers" \
           "$TMPDIR_TEST/scripts/dispatch-config-load"
  export DISPATCH_RATE_LIMITS_STATE_FILE="$TMPDIR_TEST/state/rate_limits.json"
}
rr_teardown() {
  rm -rf "$TMPDIR_TEST"; TMPDIR_TEST=""
  unset DISPATCH_RATE_LIMITS_STATE_FILE DISPATCH_REFRESH_RATE_LIMITS_CREDS \
    DISPATCH_REFRESH_RATE_LIMITS_HEADERS_FILE
}
write_creds() {  # $1=file $2=expiresAt-ms
  printf '{"claudeAiOauth":{"accessToken":"test-token","expiresAt":%s}}\n' "$2" > "$1"
}
write_headers() {  # $1=file ; remaining args are literal header lines
  local f="$1"; : > "$f"; shift; for line in "$@"; do printf '%s\n' "$line" >> "$f"; done
}

# Canonical valid headers reused across cases.
RR_H_5UTIL="anthropic-ratelimit-unified-5h-utilization: 0.22"
RR_H_5RESET="anthropic-ratelimit-unified-5h-reset: 1780611000"
RR_H_7UTIL="anthropic-ratelimit-unified-7d-utilization: 0.54"
RR_H_7RESET="anthropic-ratelimit-unified-7d-reset: 1780880400"

# CASE 1 — success: valid creds + valid headers → exit 0, canonical telemetry.
rr_setup
write_creds "$TMPDIR_TEST/fix/creds.json" 9999999999000
write_headers "$TMPDIR_TEST/fix/headers.txt" \
  "$RR_H_5UTIL" "$RR_H_5RESET" "$RR_H_7UTIL" "$RR_H_7RESET"
export DISPATCH_REFRESH_RATE_LIMITS_CREDS="$TMPDIR_TEST/fix/creds.json"
export DISPATCH_REFRESH_RATE_LIMITS_HEADERS_FILE="$TMPDIR_TEST/fix/headers.txt"
if out=$("$TMPDIR_TEST/scripts/dispatch-refresh-rate-limits" 2>/dev/null); then rc=0; else rc=$?; fi
assert_eq "refresh success → exit 0" "0" "$rc"
got=$(jq -S . "$DISPATCH_RATE_LIMITS_STATE_FILE")
want=$(printf '%s' '{"five_hour":{"used_percentage":22,"resets_at":1780611000},"seven_day":{"used_percentage":54,"resets_at":1780880400}}' | jq -S .)
assert_eq "refresh success → canonical telemetry" "$want" "$got"
rr_teardown

# CASE 2 — expired token: past expiresAt → non-zero exit, no write.
rr_setup
write_creds "$TMPDIR_TEST/fix/creds.json" 1
write_headers "$TMPDIR_TEST/fix/headers.txt" \
  "$RR_H_5UTIL" "$RR_H_5RESET" "$RR_H_7UTIL" "$RR_H_7RESET"
export DISPATCH_REFRESH_RATE_LIMITS_CREDS="$TMPDIR_TEST/fix/creds.json"
export DISPATCH_REFRESH_RATE_LIMITS_HEADERS_FILE="$TMPDIR_TEST/fix/headers.txt"
if out=$("$TMPDIR_TEST/scripts/dispatch-refresh-rate-limits" 2>/dev/null); then rc=0; else rc=$?; fi
assert_eq "expired token → non-zero exit" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
assert_eq "expired token → no state file written" "1" "$([[ ! -e "$DISPATCH_RATE_LIMITS_STATE_FILE" ]] && echo 1 || echo 0)"
rr_teardown

# CASE 3 — missing creds: nonexistent path → non-zero exit, no write.
rr_setup
write_headers "$TMPDIR_TEST/fix/headers.txt" \
  "$RR_H_5UTIL" "$RR_H_5RESET" "$RR_H_7UTIL" "$RR_H_7RESET"
export DISPATCH_REFRESH_RATE_LIMITS_CREDS="/nonexistent/creds.json"
export DISPATCH_REFRESH_RATE_LIMITS_HEADERS_FILE="$TMPDIR_TEST/fix/headers.txt"
if out=$("$TMPDIR_TEST/scripts/dispatch-refresh-rate-limits" 2>/dev/null); then rc=0; else rc=$?; fi
assert_eq "missing creds → non-zero exit" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
assert_eq "missing creds → no state file written" "1" "$([[ ! -e "$DISPATCH_RATE_LIMITS_STATE_FILE" ]] && echo 1 || echo 0)"
rr_teardown

# CASE 4 — missing headers: rate-limit headers absent → non-zero exit, no write.
rr_setup
write_creds "$TMPDIR_TEST/fix/creds.json" 9999999999000
write_headers "$TMPDIR_TEST/fix/headers.txt" \
  "HTTP/2 401" "content-type: application/json"
export DISPATCH_REFRESH_RATE_LIMITS_CREDS="$TMPDIR_TEST/fix/creds.json"
export DISPATCH_REFRESH_RATE_LIMITS_HEADERS_FILE="$TMPDIR_TEST/fix/headers.txt"
if out=$("$TMPDIR_TEST/scripts/dispatch-refresh-rate-limits" 2>/dev/null); then rc=0; else rc=$?; fi
assert_eq "missing headers → non-zero exit" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
assert_eq "missing headers → no state file written" "1" "$([[ ! -e "$DISPATCH_RATE_LIMITS_STATE_FILE" ]] && echo 1 || echo 0)"
rr_teardown

# CASE 5a — malformed utilization: 5h-utilization "abc" → non-zero exit, no write.
rr_setup
write_creds "$TMPDIR_TEST/fix/creds.json" 9999999999000
write_headers "$TMPDIR_TEST/fix/headers.txt" \
  "anthropic-ratelimit-unified-5h-utilization: abc" \
  "$RR_H_5RESET" "$RR_H_7UTIL" "$RR_H_7RESET"
export DISPATCH_REFRESH_RATE_LIMITS_CREDS="$TMPDIR_TEST/fix/creds.json"
export DISPATCH_REFRESH_RATE_LIMITS_HEADERS_FILE="$TMPDIR_TEST/fix/headers.txt"
if out=$("$TMPDIR_TEST/scripts/dispatch-refresh-rate-limits" 2>/dev/null); then rc=0; else rc=$?; fi
assert_eq "malformed utilization → non-zero exit" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
assert_eq "malformed utilization → no state file written" "1" "$([[ ! -e "$DISPATCH_RATE_LIMITS_STATE_FILE" ]] && echo 1 || echo 0)"
rr_teardown

# CASE 5b — malformed reset: 5h-reset "12.5" (non-integer) → non-zero exit, no write.
rr_setup
write_creds "$TMPDIR_TEST/fix/creds.json" 9999999999000
write_headers "$TMPDIR_TEST/fix/headers.txt" \
  "$RR_H_5UTIL" \
  "anthropic-ratelimit-unified-5h-reset: 12.5" \
  "$RR_H_7UTIL" "$RR_H_7RESET"
export DISPATCH_REFRESH_RATE_LIMITS_CREDS="$TMPDIR_TEST/fix/creds.json"
export DISPATCH_REFRESH_RATE_LIMITS_HEADERS_FILE="$TMPDIR_TEST/fix/headers.txt"
if out=$("$TMPDIR_TEST/scripts/dispatch-refresh-rate-limits" 2>/dev/null); then rc=0; else rc=$?; fi
assert_eq "malformed reset → non-zero exit" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
assert_eq "malformed reset → no state file written" "1" "$([[ ! -e "$DISPATCH_RATE_LIMITS_STATE_FILE" ]] && echo 1 || echo 0)"
rr_teardown

# CASE 5c — tampered token: a token with characters outside the OAuth set
# (a space) fails the charset guard before any header is placed → no write.
rr_setup
printf '{"claudeAiOauth":{"accessToken":"bad token","expiresAt":9999999999000}}\n' > "$TMPDIR_TEST/fix/creds.json"
write_headers "$TMPDIR_TEST/fix/headers.txt" \
  "$RR_H_5UTIL" "$RR_H_5RESET" "$RR_H_7UTIL" "$RR_H_7RESET"
export DISPATCH_REFRESH_RATE_LIMITS_CREDS="$TMPDIR_TEST/fix/creds.json"
export DISPATCH_REFRESH_RATE_LIMITS_HEADERS_FILE="$TMPDIR_TEST/fix/headers.txt"
if out=$("$TMPDIR_TEST/scripts/dispatch-refresh-rate-limits" 2>/dev/null); then rc=0; else rc=$?; fi
assert_eq "tampered token → non-zero exit" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
assert_eq "tampered token → no state file written" "1" "$([[ ! -e "$DISPATCH_RATE_LIMITS_STATE_FILE" ]] && echo 1 || echo 0)"
rr_teardown

# CASE 5d — bad model override: a model name with a quote fails the charset
# guard before the JSON body is built → no write.
rr_setup
write_creds "$TMPDIR_TEST/fix/creds.json" 9999999999000
write_headers "$TMPDIR_TEST/fix/headers.txt" \
  "$RR_H_5UTIL" "$RR_H_5RESET" "$RR_H_7UTIL" "$RR_H_7RESET"
export DISPATCH_REFRESH_RATE_LIMITS_CREDS="$TMPDIR_TEST/fix/creds.json"
export DISPATCH_REFRESH_RATE_LIMITS_HEADERS_FILE="$TMPDIR_TEST/fix/headers.txt"
export DISPATCH_REFRESH_RATE_LIMITS_MODEL='haiku","injected":"x'
if out=$("$TMPDIR_TEST/scripts/dispatch-refresh-rate-limits" 2>/dev/null); then rc=0; else rc=$?; fi
unset DISPATCH_REFRESH_RATE_LIMITS_MODEL
assert_eq "bad model override → non-zero exit" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
assert_eq "bad model override → no state file written" "1" "$([[ ! -e "$DISPATCH_RATE_LIMITS_STATE_FILE" ]] && echo 1 || echo 0)"
rr_teardown

# CASE 5e — non-https endpoint: with the network branch taken (no headers seam),
# a non-https ENDPOINT trips the TLS guard and exits before curl runs — the
# bearer token is never sent in cleartext, and no state file is written.
rr_setup
write_creds "$TMPDIR_TEST/fix/creds.json" 9999999999000
export DISPATCH_REFRESH_RATE_LIMITS_CREDS="$TMPDIR_TEST/fix/creds.json"
export DISPATCH_REFRESH_RATE_LIMITS_ENDPOINT="http://127.0.0.1:9/never"
if out=$("$TMPDIR_TEST/scripts/dispatch-refresh-rate-limits" 2>/dev/null); then rc=0; else rc=$?; fi
unset DISPATCH_REFRESH_RATE_LIMITS_ENDPOINT
assert_eq "non-https endpoint → non-zero exit" "1" "$([[ "$rc" -ne 0 ]] && echo 1 || echo 0)"
assert_eq "non-https endpoint → no state file written" "1" "$([[ ! -e "$DISPATCH_RATE_LIMITS_STATE_FILE" ]] && echo 1 || echo 0)"
rr_teardown

# CASE 6 — refresh→budget regression for #1127. Seed a FROZEN pre-reset file
# (used 95%, resets_at in the past); the probe overwrites it with reopened-window
# telemetry; the REAL dispatch-target-workers then computes a positive target
# from the refreshed file — the end-to-end self-resume the issue requires.
rr_setup
printf '{"five_hour":{"used_percentage":95,"resets_at":1},"seven_day":{"used_percentage":95,"resets_at":1}}\n' > "$DISPATCH_RATE_LIMITS_STATE_FILE"
write_creds "$TMPDIR_TEST/fix/creds.json" 9999999999000
RR_R7=$(tw_resets_for_x 0.5)         # mid-week 7d reset
RR_R5=$((TW_NOW + 18000))            # 5h reset comfortably in the future
write_headers "$TMPDIR_TEST/fix/headers.txt" \
  "anthropic-ratelimit-unified-5h-utilization: 0.05" \
  "anthropic-ratelimit-unified-5h-reset: $RR_R5" \
  "anthropic-ratelimit-unified-7d-utilization: 0.10" \
  "anthropic-ratelimit-unified-7d-reset: $RR_R7"
export DISPATCH_REFRESH_RATE_LIMITS_CREDS="$TMPDIR_TEST/fix/creds.json"
export DISPATCH_REFRESH_RATE_LIMITS_HEADERS_FILE="$TMPDIR_TEST/fix/headers.txt"
if out=$("$TMPDIR_TEST/scripts/dispatch-refresh-rate-limits" 2>/dev/null); then rc=0; else rc=$?; fi
assert_eq "regression: probe refreshed reopened window → exit 0" "0" "$rc"
export DISPATCH_TARGET_WORKERS_RATE_LIMITS_PATH="$DISPATCH_RATE_LIMITS_STATE_FILE"
export DISPATCH_TARGET_WORKERS_NOW="$TW_NOW"
target=$("$TMPDIR_TEST/scripts/dispatch-target-workers" 2>/dev/null)
TOTAL=$((TOTAL + 1))
if [[ "$target" =~ ^[0-9]+$ && "$target" -ge 1 ]]; then
  PASS=$((PASS + 1)); echo "  PASS: regression: reopened window → target >= 1 (got $target)"
else
  FAIL=$((FAIL + 1)); echo "  FAIL: regression: reopened window → target >= 1 (got '$target')"
fi
unset DISPATCH_TARGET_WORKERS_RATE_LIMITS_PATH DISPATCH_TARGET_WORKERS_NOW
rr_teardown

echo ""
echo "=== dispatch-sample-usage / usage-sample-writer ==="

# Writer side of #1007 (epic #1005's Capacity view). Two scripts under test:
#   usage-sample-writer.mjs — firebase-admin writer; run here ONLY in --dry-run,
#     so firebase-admin is NEVER imported and no network/credentials are touched.
#     The DISPATCH_USAGE_SAMPLES_NOW seam pins sampledAt/expireAt for determinism.
#   dispatch-sample-usage — the local sampler. Its rate-limits path, busy-worker
#     count (CLAUDE_AGENTS_CMD), target-workers binary, and writer binary are all
#     replaced by seams/fakes, so the sampler tests never hit a real daemon or
#     firebase-admin either: a FAKE writer captures the assembled payload.

su_setup() {
  TMPDIR_TEST=$(mktemp -d)
  mkdir -p "$TMPDIR_TEST/scripts" "$TMPDIR_TEST/fix"
  # Copy everything the two scripts source/exec so default SCRIPT_DIR resolution
  # works; the sampler tests still override the writer + target via seams.
  cp "$SCRIPT_DIR/usage-sample-writer.mjs" "$TMPDIR_TEST/scripts/"
  cp "$SCRIPT_DIR/dispatch-sample-usage" "$TMPDIR_TEST/scripts/"
  cp "$SCRIPT_DIR/lib-claude-agents.sh" "$TMPDIR_TEST/scripts/"
  cp "$SCRIPT_DIR/dispatch-target-workers" "$TMPDIR_TEST/scripts/"
  cp "$SCRIPT_DIR/dispatch-config-load" "$TMPDIR_TEST/scripts/"
  cp "$SCRIPT_DIR/lib.sh" "$TMPDIR_TEST/scripts/"
  chmod +x "$TMPDIR_TEST/scripts/usage-sample-writer.mjs" \
           "$TMPDIR_TEST/scripts/dispatch-sample-usage" \
           "$TMPDIR_TEST/scripts/dispatch-target-workers" \
           "$TMPDIR_TEST/scripts/dispatch-config-load"
}
su_teardown() {
  rm -rf "$TMPDIR_TEST"; TMPDIR_TEST=""
  unset DISPATCH_USAGE_SAMPLES_ENABLED DISPATCH_USAGE_SAMPLES_GROUP_ID \
    DISPATCH_USAGE_SAMPLES_NAMESPACE DISPATCH_USAGE_SAMPLES_TTL_DAYS \
    DISPATCH_USAGE_SAMPLES_PROJECT_ID DISPATCH_USAGE_SAMPLES_NOW \
    DISPATCH_USAGE_SAMPLES_RATE_LIMITS_PATH DISPATCH_USAGE_SAMPLES_TARGET_WORKERS_CMD \
    DISPATCH_USAGE_SAMPLES_WRITER CLAUDE_AGENTS_CMD \
    DISPATCH_USAGE_SAMPLES_SECRET_OVERRIDE DISPATCH_USAGE_SAMPLES_SECRET_NAME
}

# Fixed epoch for writer determinism: sampledAt=1780600000, TTL 60d →
# expireAt=1780600000 + 60*86400 = 1785784000.
SU_NOW=1780600000
SU_EXPIRE=1785784000   # SU_NOW + 60*86400

WRITER() { printf '%s' "$1" | "$TMPDIR_TEST/scripts/usage-sample-writer.mjs" --dry-run; }

# Write a fake `claude` that prints a fixed JSON blob for any args (the lib calls
# `claude agents --json` with and without --cwd). $1=dest $2=json-literal.
su_write_fake_claude() {
  printf '#!/usr/bin/env bash\nprintf %%s %s\n' "'$2'" > "$1"
  chmod +x "$1"
}

# --- WRITER (--dry-run) cases ----------------------------------------------

# W1 — full valid payload + valid config (default namespace + TTL) → exit 0;
# all 9 schema fields + expireAt present; spot-checked values match input/config;
# sampledAt/expireAt epochs match NOW and NOW+TTL*86400.
su_setup
export DISPATCH_USAGE_SAMPLES_SECRET_OVERRIDE="a@b.com,c@d.com"
export DISPATCH_USAGE_SAMPLES_GROUP_ID="grp-1"
export DISPATCH_USAGE_SAMPLES_NOW="$SU_NOW"
W1_PAYLOAD='{"fiveHourUsedPct":4,"weeklyUsedPct":84,"fiveHourResetsAt":1780867800,"weeklyResetsAt":1780880400,"activeWorkers":1,"targetWorkers":3}'
if out=$(WRITER "$W1_PAYLOAD" 2>/dev/null); then rc=0; else rc=$?; fi
assert_eq "writer W1 valid → exit 0" "0" "$rc"
assert_eq "writer W1 → has all schema fields + expireAt" "1" \
  "$(jq -e 'has("sampledAt") and has("fiveHourUsedPct") and has("weeklyUsedPct") and has("fiveHourResetsAt") and has("weeklyResetsAt") and has("activeWorkers") and has("targetWorkers") and has("groupId") and has("memberEmails") and has("expireAt")' <<<"$out" >/dev/null 2>&1 && echo 1 || echo 0)"
assert_eq "writer W1 → fiveHourUsedPct" "4" "$(jq -r '.fiveHourUsedPct' <<<"$out")"
assert_eq "writer W1 → weeklyUsedPct" "84" "$(jq -r '.weeklyUsedPct' <<<"$out")"
assert_eq "writer W1 → activeWorkers" "1" "$(jq -r '.activeWorkers' <<<"$out")"
assert_eq "writer W1 → targetWorkers" "3" "$(jq -r '.targetWorkers' <<<"$out")"
assert_eq "writer W1 → groupId" "grp-1" "$(jq -r '.groupId' <<<"$out")"
assert_eq "writer W1 → memberEmails" '["a@b.com","c@d.com"]' "$(jq -c '.memberEmails' <<<"$out")"
assert_eq "writer W1 → sampledAt epoch == NOW" "$SU_NOW" \
  "$(date -u -d "$(jq -r '.sampledAt' <<<"$out")" +%s)"
assert_eq "writer W1 → expireAt epoch == NOW + TTL*86400" "$SU_EXPIRE" \
  "$(date -u -d "$(jq -r '.expireAt' <<<"$out")" +%s)"
su_teardown

# W2 — null resets pass through as JSON null; exit 0, no crash.
su_setup
export DISPATCH_USAGE_SAMPLES_SECRET_OVERRIDE="a@b.com"
export DISPATCH_USAGE_SAMPLES_GROUP_ID="grp-1"
export DISPATCH_USAGE_SAMPLES_NOW="$SU_NOW"
W2_PAYLOAD='{"fiveHourUsedPct":4,"weeklyUsedPct":84,"fiveHourResetsAt":null,"weeklyResetsAt":null,"activeWorkers":0,"targetWorkers":2}'
if out=$(WRITER "$W2_PAYLOAD" 2>/dev/null); then rc=0; else rc=$?; fi
assert_eq "writer W2 null resets → exit 0" "0" "$rc"
assert_eq "writer W2 → fiveHourResetsAt null" "null" "$(jq -r '.fiveHourResetsAt' <<<"$out")"
assert_eq "writer W2 → weeklyResetsAt null" "null" "$(jq -r '.weeklyResetsAt' <<<"$out")"
su_teardown

