#          AND stdout is EMPTY (buffer-then-flush, no partial pack)
# ---------------------------------------------------------------------------
echo "Test: ctxpack failed gh mid-build exits non-zero with EMPTY stdout"
ctxpack_setup

# fail-issue-view marker causes gh stub to exit 1 with a non-transient message.
